def search(a, start, remaining, current, out):
    if remaining == 0:
        out.append(" ".join(map(str, current)))
        return
    for i in range(start, len(a)):
        if a[i] > remaining:
            break                          # a is sorted: the rest is too large too
        current.append(a[i])
        search(a, i, remaining - a[i], current, out)     # i, not i + 1: reuse is allowed
        current.pop()

